// Récupérer les données d'entrée
const data = $input.first().json;

// Générer le contenu de site-config.ts
const escapeString = (str) => {
  if (!str) return '';
  return String(str).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n');
};

const siteConfig = `/**
 * Configuration du site - ${escapeString(data.nom_salon)}
 * Généré automatiquement le ${new Date().toLocaleDateString('fr-FR')}
 */

export const siteConfig = {
  name: "${escapeString(data.nom_salon)}",
  owner: "${escapeString(data.nom_proprietaire)}",
  tagline: "${escapeString(data.tagline || 'Votre spécialité')}",

  phone: "${escapeString(data.telephone)}",
  phoneLink: "tel:+33${data.telephone ? data.telephone.replace(/\\s/g, '').replace(/^0/, '') : ''}",
  email: "${escapeString(data.email)}",

  address: {
    street: "${escapeString(data.adresse_rue)}",
    city: "${escapeString(data.ville)}",
    postalCode: "${escapeString(data.code_postal)}",
    full: "${escapeString(data.adresse_rue)}, ${escapeString(data.code_postal)} ${escapeString(data.ville)}",
  },

  googleMapsUrl: "${escapeString(data.google_maps_url || 'https://maps.google.com')}",
  googleMapsEmbedUrl: "${escapeString(data.google_maps_embed_url || '')}",
  googleRating: ${data.google_rating || 5.0},
  googleReviewCount: ${data.google_review_count || 0},

  heroImage: "${escapeString(data.image_hero || 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=1920&q=80')}",
  ownerImage: "${escapeString(data.image_proprietaire || '')}",

  colors: {
    primary: "${escapeString(data.couleur_primaire || '')}",
  },

  hero: {
    title: {
      line1: "${escapeString(data.hero_ligne1 || 'Retrouvez')}",
      line2: "${escapeString(data.hero_ligne2 || 'Bien-être')}",
      line3: "${escapeString(data.hero_ligne3 || '& Sérénité')}",
    },
    description: "${escapeString(data.hero_description || 'Découvrez nos soins personnalisés pour retrouver équilibre et harmonie.')}",
  },

  services: [
    {
      id: "service-1",
      name: "${escapeString(data.service_1_nom || 'Soin Découverte')}",
      description: "${escapeString(data.service_1_description || 'Une première approche pour découvrir les bienfaits.')}",
      duration: "${escapeString(data.service_1_duree || '45 min')}",
      price: ${data.service_1_prix || 45},
      image: "${escapeString(data.service_1_image || 'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?w=600&q=80')}",
    },
    {
      id: "service-2",
      name: "${escapeString(data.service_2_nom || 'Soin Complet')}",
      description: "${escapeString(data.service_2_description || 'Un soin approfondi pour une relaxation totale.')}",
      duration: "${escapeString(data.service_2_duree || '60 min')}",
      price: ${data.service_2_prix || 60},
      image: "${escapeString(data.service_2_image || 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=600&q=80')}",
    },
    {
      id: "service-3",
      name: "${escapeString(data.service_3_nom || 'Soin Premium')}",
      description: "${escapeString(data.service_3_description || 'Notre soin signature pour une expérience unique.')}",
      duration: "${escapeString(data.service_3_duree || '90 min')}",
      price: ${data.service_3_prix || 85},
      image: "${escapeString(data.service_3_image || 'https://images.unsplash.com/photo-1515377905703-c4788e51af15?w=600&q=80')}",
    },
  ],

  benefits: [
    {
      title: "${escapeString(data.bienfait_1_titre || 'Réduction du stress')}",
      description: "${escapeString(data.bienfait_1_description || 'Libération des tensions accumulées et apaisement.')}",
      icon: "Brain",
    },
    {
      title: "${escapeString(data.bienfait_2_titre || 'Amélioration du sommeil')}",
      description: "${escapeString(data.bienfait_2_description || 'Favorise un sommeil réparateur.')}",
      icon: "Moon",
    },
    {
      title: "${escapeString(data.bienfait_3_titre || "Boost d'énergie")}",
      description: "${escapeString(data.bienfait_3_description || 'Stimule et revitalise.')}",
      icon: "Zap",
    },
    {
      title: "${escapeString(data.bienfait_4_titre || 'Soulagement des douleurs')}",
      description: "${escapeString(data.bienfait_4_description || 'Atténue les tensions musculaires.')}",
      icon: "Heart",
    },
  ],

  reviews: [
    {
      author: "${escapeString(data.avis_1_auteur || 'Client satisfait')}",
      text: "${escapeString(data.avis_1_texte || 'Excellente expérience, je recommande !')}",
      rating: 5,
    },
    {
      author: "${escapeString(data.avis_2_auteur || 'Client satisfait')}",
      text: "${escapeString(data.avis_2_texte || 'Très professionnel et accueillant.')}",
      rating: 5,
    },
    {
      author: "${escapeString(data.avis_3_auteur || 'Client satisfait')}",
      text: "${escapeString(data.avis_3_texte || 'Je me sens tellement mieux après chaque séance.')}",
      rating: 5,
    },
  ],

  about: {
    title: "Les bienfaits de nos soins",
    description: "${escapeString(data.about_description || 'Technique naturelle et non invasive pour retrouver équilibre et harmonie.')}",
    credentials: [
      "${escapeString(data.credential_1 || 'Certifié(e)')}",
      "${escapeString(data.credential_2 || 'Approche personnalisée')}",
      "${escapeString(data.credential_3 || 'Expérience')}",
    ],
  },

  seo: {
    title: "${escapeString(data.nom_salon)} | ${escapeString(data.ville)}",
    description: "${escapeString(data.seo_description || 'Découvrez nos soins bien-être. Prenez rendez-vous.')}",
    keywords: "${escapeString(data.seo_keywords || 'bien-être, soins, relaxation')}",
  },

  social: {
    facebook: "${escapeString(data.facebook_url || '')}",
    instagram: "${escapeString(data.instagram_url || '')}",
    linkedin: "${escapeString(data.linkedin_url || '')}",
  },
}

export type SiteConfig = typeof siteConfig
`;

// Encoder en base64 pour l'API GitHub
const configBase64 = Buffer.from(siteConfig).toString('base64');

return {
  json: {
    ...data,
    configContent: configBase64,
    configPath: 'lib/site-config.ts'
  }
};
